/**
 * The brownout's darkness (S3-01): a screen-sized layer of near-black, with every light cut out of
 * it each frame. What's under a cut-out shows; everything else is (almost) black.
 *
 * How: a Phaser RenderTexture (a picture I can draw into at run time). Every frame it's cleared,
 * filled with the dark colour, and then each light is drawn into it with the ERASE blend mode,
 * which removes the darkness where the light's pixels are (the light's alpha says how much). The
 * lights are white shapes generated by scripts/make-assets.ts:
 *   light.png  a round light, strength in 4 steps (doorways, candles, the glow around each tanod)
 *   cone.png   the flashlight cone, pointing right; rotated to where each tanod faces
 * and safe zones are rectangles, fully lit.
 *
 * The layer never scrolls (scroll factor 0), so world positions are turned into screen positions
 * by subtracting the camera's top-left corner, rounded to whole pixels to stay crisp.
 */
import Phaser from "phaser";

/** A round light at a world position (pixels); `size` = its diameter in pixels. */
export interface Glow {
  readonly x: number;
  readonly y: number;
  readonly size: number;
}
/** A flashlight at a world position (pixels), pointing at `angle` (radians, 0 = right). */
export interface Beam {
  readonly x: number;
  readonly y: number;
  readonly angle: number;
}
/** A fully lit rectangle in world pixels (a safe zone). */
export interface Area {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** The dark colour: a very deep night blue rather than pure black, so it still feels like night. */
const DARK = 0x04060c;

export class Darkness {
  private readonly layer: Phaser.GameObjects.RenderTexture;
  /** Stamps used to erase: never shown themselves (not added to the scene's display list). */
  private readonly glow: Phaser.GameObjects.Image;
  private readonly beam: Phaser.GameObjects.Image;
  private readonly box: Phaser.GameObjects.Rectangle;

  constructor(scene: Phaser.Scene, depth: number) {
    const { width, height } = scene.scale;
    this.layer = scene.add
      .renderTexture(0, 0, width, height)
      .setOrigin(0)
      .setScrollFactor(0)
      .setDepth(depth)
      .setVisible(false);
    // `new …` (not `scene.add…`) makes an object that isn't on the display list: never drawn.
    this.glow = new Phaser.GameObjects.Image(scene, 0, 0, "light");
    this.beam = new Phaser.GameObjects.Image(scene, 0, 0, "cone").setOrigin(0, 0.5); // apex = torch
    this.box = new Phaser.GameObjects.Rectangle(scene, 0, 0, 1, 1, 0xffffff).setOrigin(0);
  }

  /**
   * Redraws the darkness for this frame. `strength` is how dark (0 = off, 1 = black); the lights
   * are in world pixels.
   */
  draw(
    camera: Phaser.Cameras.Scene2D.Camera,
    strength: number,
    glows: readonly Glow[],
    beams: readonly Beam[],
    areas: readonly Area[],
  ): void {
    this.layer.setVisible(strength > 0);
    if (strength <= 0) return;
    // World → screen: subtract the visible area's top-left corner.
    const ox = Math.round(camera.worldView.x);
    const oy = Math.round(camera.worldView.y);
    // Phaser 4 queues drawing commands and runs them on render(), reading each object's position
    // THEN. The same stamp is moved for every light, so each erase must be rendered before the
    // stamp moves on; otherwise every light would land where the last one is.
    this.layer.clear().fill(DARK, strength).render();
    for (const a of areas) {
      this.box.setPosition(a.x - ox, a.y - oy).setSize(a.width, a.height);
      this.layer.erase(this.box).render();
    }
    for (const g of glows) {
      this.glow.setPosition(Math.round(g.x) - ox, Math.round(g.y) - oy).setScale(g.size / 64);
      this.layer.erase(this.glow).render();
    }
    for (const b of beams) {
      this.beam.setPosition(Math.round(b.x) - ox, Math.round(b.y) - oy).setRotation(b.angle);
      this.layer.erase(this.beam).render();
    }
  }
}
